SELECT 
  FROM ai_session s
 WHERE s.user_id = #{userId}
   AND s.context_type = #{contextType}
   AND s.context_resource_id = #{contextResourceId}

SELECT 
  FROM ai_session s
 WHERE s.user_id = #{userId} AND s.session_id = #{sessionId}

SELECT COUNT(*) FROM (
  SELECT 1 FROM ai_session s WHERE s.session_id = #{sessionId} AND s.user_id <> #{userId}
  ) x

mapper.update:
UPDATE ai_session
   SET title = #{title},
       updated_at = #{now}
 WHERE id = #{id}

