SELECT , s.channel_source, s.slack_team_id, s.slack_channel_id, s.slack_thread_ts
  FROM ai_session s
 WHERE s.channel_source = 'SLACK'
   AND s.slack_team_id = #{teamId}
   AND s.slack_channel_id = #{channelId}
   AND s.slack_thread_ts = #{threadTs}
